def main(root):
 root=Path(root).resolve(); targets=[root/'academic_payload/index.html',root/'app/src/main/assets/www/index.html']
 inj='<script id="v188-pencil-batch3">\n'+'\n'.join("window.ORG_SYSTEM_DIAGRAMS[%s]=(window.ORG_SYSTEM_DIAGRAMS[%s]||'')+%s;"%(json.dumps(k),json.dumps(k),json.dumps(''.join(P[x] for x in v),ensure_ascii=False)) for k,v in ADD.items())+'\n</script>\n'
 for p in targets:
  s=p.read_text(encoding='utf-8'); anchor='<script id="v188-contextual-atlas">'
  if 'id="v188-pencil-batch3"' in s: raise SystemExit('batch3 already applied')
  if anchor not in s: raise SystemExit('contextual atlas anchor missing')
  p.write_text(s.replace(anchor,inj+anchor,1),encoding='utf-8',newline='\n')
 if targets[0].read_bytes()!=targets[1].read_bytes(): raise SystemExit('payload copies diverged')
 print('V188_BATCH3_PENCIL_SVGS_CREATED='+str(len(P)))
 print('V188_BATCH3_LESSONS_AFFECTED='+str(len(ADD)))
 print('V188_BUILD_TRIGGERED=NO')
 print('V188_ILLUSTRATION_GATE_COMPLETE=NO')
if __name__=='__main__': main(sys.argv[1])
